@neolit123 the reason this occurs is because the controller has no resync interval combined with a sync loop that ignores errors.  Hence it only runs once on KCM start up and afterwards is only triggered when the `kube-public/cluster-info` config map is updated or when a bootstrap token is updated.  While having no resync interval is perfectly valid, combining that with a sync loop that ignores errors is not.

If we wanted to remove the lack of a resync interval (which I would not recommend), you could do something like (this would cause a re-run of the loop every 12 hours on default config):

```diff
diff --git a/pkg/controller/bootstrap/bootstrapsigner.go b/pkg/controller/bootstrap/bootstrapsigner.go
index a087ae23a60..acaf8bc41f6 100644
--- a/pkg/controller/bootstrap/bootstrapsigner.go
+++ b/pkg/controller/bootstrap/bootstrapsigner.go
@@ -18,12 +18,8 @@ package bootstrap
 
 import (
 	"context"
-	"strings"
-	"time"
-
-	"k8s.io/klog/v2"
-
 	"fmt"
+	"strings"
 
 	v1 "k8s.io/api/core/v1"
 	apierrors "k8s.io/apimachinery/pkg/api/errors"
@@ -39,6 +35,7 @@ import (
 	bootstrapapi "k8s.io/cluster-bootstrap/token/api"
 	jws "k8s.io/cluster-bootstrap/token/jws"
 	"k8s.io/component-base/metrics/prometheus/ratelimiter"
+	"k8s.io/klog/v2"
 	api "k8s.io/kubernetes/pkg/apis/core"
 )
 
@@ -52,14 +49,6 @@ type SignerOptions struct {
 
 	// TokenSecretNamespace string is the namespace for token Secrets.
 	TokenSecretNamespace string
-
-	// ConfigMapResync is the time.Duration at which to fully re-list configmaps.
-	// If zero, re-list will be delayed as long as possible
-	ConfigMapResync time.Duration
-
-	// SecretResync is the time.Duration at which to fully re-list secrets.
-	// If zero, re-list will be delayed as long as possible
-	SecretResync time.Duration
 }
 
 // DefaultSignerOptions returns a set of default options for creating a Signer.
@@ -112,7 +101,7 @@ func NewSigner(cl clientset.Interface, secrets informers.SecretInformer, configM
 		}
 	}
 
-	configMaps.Informer().AddEventHandlerWithResyncPeriod(
+	configMaps.Informer().AddEventHandler(
 		cache.FilteringResourceEventHandler{
 			FilterFunc: func(obj interface{}) bool {
 				switch t := obj.(type) {
@@ -128,10 +117,9 @@ func NewSigner(cl clientset.Interface, secrets informers.SecretInformer, configM
 				UpdateFunc: func(_, _ interface{}) { e.pokeConfigMapSync() },
 			},
 		},
-		options.ConfigMapResync,
 	)
 
-	secrets.Informer().AddEventHandlerWithResyncPeriod(
+	secrets.Informer().AddEventHandler(
 		cache.FilteringResourceEventHandler{
 			FilterFunc: func(obj interface{}) bool {
 				switch t := obj.(type) {
@@ -148,7 +136,6 @@ func NewSigner(cl clientset.Interface, secrets informers.SecretInformer, configM
 				DeleteFunc: func(_ interface{}) { e.pokeConfigMapSync() },
 			},
 		},
-		options.SecretResync,
 	)
 
 	return e, nil
```

The better solution is to not ignore errors.  The controller should simply keep retrying forever with an exponential backoff.

